const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const pts = [];
for (let i = 0; i < n; i++) pts.push([tok[1 + 2 * i], tok[2 + 2 * i]]);
pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
const d2 = (a, b) => (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]);
function solve(l, r) {
  if (r - l <= 3) {
    let best = Infinity;
    for (let i = l; i < r; i++) for (let j = i + 1; j < r; j++) best = Math.min(best, d2(pts[i], pts[j]));
    return best;
  }
  const m = (l + r) >> 1, midx = pts[m][0];
  let best = Math.min(solve(l, m), solve(m, r));
  const strip = pts.slice(l, r).filter((p) => (p[0] - midx) * (p[0] - midx) < best);
  strip.sort((a, b) => a[1] - b[1]);
  for (let i = 0; i < strip.length; i++) {
    for (let j = i + 1; j < strip.length && (strip[j][1] - strip[i][1]) * (strip[j][1] - strip[i][1]) < best; j++) {
      best = Math.min(best, d2(strip[i], strip[j]));
    }
  }
  return best;
}
console.log(String(solve(0, n)));

