import java.io.*;
import java.util.*;

public class Main {
    static long[][] pts;

    static long d2(long[] a, long[] b) {
        return (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]);
    }

    static long solve(int l, int r) {
        if (r - l <= 3) {
            long best = Long.MAX_VALUE;
            for (int i = l; i < r; i++) for (int j = i + 1; j < r; j++) best = Math.min(best, d2(pts[i], pts[j]));
            return best;
        }
        int m = (l + r) / 2;
        long midx = pts[m][0];
        long best = Math.min(solve(l, m), solve(m, r));
        List<long[]> strip = new ArrayList<>();
        for (int i = l; i < r; i++) if ((pts[i][0] - midx) * (pts[i][0] - midx) < best) strip.add(pts[i]);
        strip.sort((a, b) -> Long.compare(a[1], b[1]));
        for (int i = 0; i < strip.size(); i++)
            for (int j = i + 1; j < strip.size() && (strip.get(j)[1] - strip.get(i)[1]) * (strip.get(j)[1] - strip.get(i)[1]) < best; j++)
                best = Math.min(best, d2(strip.get(i), strip.get(j)));
        return best;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        pts = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); pts[i][0] = (long) in.nval;
            in.nextToken(); pts[i][1] = (long) in.nval;
        }
        Arrays.sort(pts, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        System.out.println(solve(0, n));
    }
}

