#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
vector<P> pts;

ll d2(const P& a, const P& b) { return (a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second); }

ll solve(int l, int r) {
    if (r - l <= 3) {
        ll best = LLONG_MAX;
        for (int i = l; i < r; i++) for (int j = i + 1; j < r; j++) best = min(best, d2(pts[i], pts[j]));
        return best;
    }
    int m = (l + r) / 2;
    ll midx = pts[m].first;
    ll best = min(solve(l, m), solve(m, r));
    vector<P> strip;
    for (int i = l; i < r; i++) if ((pts[i].first - midx) * (pts[i].first - midx) < best) strip.push_back(pts[i]);
    sort(strip.begin(), strip.end(), [](const P& a, const P& b) { return a.second < b.second; });
    for (size_t i = 0; i < strip.size(); i++)
        for (size_t j = i + 1; j < strip.size() && (strip[j].second - strip[i].second) * (strip[j].second - strip[i].second) < best; j++)
            best = min(best, d2(strip[i], strip[j]));
    return best;
}

int main() {
    int n;
    scanf("%d", &n);
    pts.resize(n);
    for (auto& p : pts) scanf("%lld %lld", &p.first, &p.second);
    sort(pts.begin(), pts.end());
    printf("%lld\n", solve(0, n));
    return 0;
}
